/**
 * Swarm Completion Coordinator (ADR-058)
 *
 * Tracks swarm task completion state and provides programmatic API
 * for the Autopilot persistent completion loop. Integrates with
 * the self-improvement pipeline for learning from completion patterns.
 */

import { DriftDetector, DriftMetrics, DriftSignal } from './drift-detector.js';

export interface SwarmTask {
  id: string;
  subject: string;
  status: 'pending' | 'in_progress' | 'completed' | 'blocked';
  owner?: string;
  source?: string;
  createdAt?: number;
  completedAt?: number;
}

export interface CompletionState {
  total: number;
  completed: number;
  inProgress: number;
  pending: number;
  blocked: number;
  progress: number;
  isComplete: boolean;
  iterations: number;
  elapsedMs: number;
  remainingTasks: SwarmTask[];
}

export interface CompletionConfig {
  maxIterations: number;
  timeoutMinutes: number;
  enabled: boolean;
}

const DEFAULT_CONFIG: CompletionConfig = {
  maxIterations: 50,
  timeoutMinutes: 240,
  enabled: true,
};

export class SwarmCompletionCoordinator {
  private tasks = new Map<string, SwarmTask>();
  private iterations = 0;
  private startTime = Date.now();
  private config: CompletionConfig;
  private completionHistory: Array<{
    taskId: string;
    duration: number;
    iterations: number;
  }> = [];
  private driftDetector: DriftDetector;
  private sessionId: string;
  private lastDriftCheck = 0;
  private learningInitialized = false;
  private learning: any = null; // AutopilotLearning (lazy loaded)

  constructor(config: Partial<CompletionConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.driftDetector = new DriftDetector();
    this.sessionId = `session-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  }

  /**
   * Register a task for completion tracking.
   */
  addTask(task: SwarmTask): void {
    this.tasks.set(task.id, { ...task, createdAt: task.createdAt || Date.now() });
  }

  /**
   * Bulk register tasks.
   */
  addTasks(tasks: SwarmTask[]): void {
    for (const task of tasks) {
      this.addTask(task);
    }
  }

  /**
   * Update task status with optional agent tracking for drift detection.
   */
  updateTask(taskId: string, status: SwarmTask['status'], agentId?: string): void {
    const task = this.tasks.get(taskId);
    if (task) {
      const previousOwner = task.owner;
      task.status = status;
      if (agentId) task.owner = agentId;

      if (status === 'completed') {
        task.completedAt = Date.now();
        this.completionHistory.push({
          taskId,
          duration: task.completedAt - (task.createdAt || this.startTime),
          iterations: this.iterations,
        });
        // Record success episode if learning available
        if (this.learning) {
          this.learning.recordTaskCompletion({
            taskId,
            subject: task.subject,
            status: 'completed',
            iterations: this.iterations,
            durationMs: task.completedAt - (task.createdAt || this.startTime),
          }).catch(() => {});
        }
      } else if (status === 'blocked' || status === 'pending') {
        // Track failures for drift detection
        this.driftDetector.recordTaskFailure(taskId);
        if (this.learning) {
          this.learning.recordTaskFailure({
            taskId,
            subject: task.subject,
            status,
            iterations: this.iterations,
            durationMs: Date.now() - (task.createdAt || this.startTime),
          }).catch(() => {});
        }
      }

      // Track reassignments
      if (agentId && previousOwner && agentId !== previousOwner) {
        this.driftDetector.recordAgentReassignment(taskId, previousOwner, agentId);
      }
    }
  }

  /**
   * Remove a task from tracking.
   */
  removeTask(taskId: string): void {
    this.tasks.delete(taskId);
  }

  /**
   * Increment iteration counter, run drift detection, and return current state.
   * Called by the Stop hook on each re-engagement cycle.
   */
  tick(): CompletionState {
    this.iterations++;
    const state = this.getState();

    // Record iteration for drift detection
    this.driftDetector.recordIteration({ completed: state.completed });

    // Check for drift every 3+ iterations since last check
    if (this.iterations - this.lastDriftCheck >= 3) {
      const signals = this.driftDetector.detectDrift();
      if (signals.length > 0) {
        this.applyMitigation(signals);
      }
      this.lastDriftCheck = this.iterations;

      // Record SONA trajectory step if learning available
      if (this.learning) {
        this.learning.recordIterationStep(state, signals).catch(() => {});
      }
    }

    return state;
  }

  /**
   * Get current completion state without incrementing iterations.
   */
  getState(): CompletionState {
    let completedCount = 0;
    let inProgressCount = 0;
    let pendingCount = 0;
    let blockedCount = 0;
    const remaining: SwarmTask[] = [];

    for (const task of this.tasks.values()) {
      switch (task.status) {
        case 'completed': completedCount++; break;
        case 'in_progress': inProgressCount++; remaining.push(task); break;
        case 'pending': pendingCount++; remaining.push(task); break;
        case 'blocked': blockedCount++; remaining.push(task); break;
        default: remaining.push(task); break;
      }
    }

    const total = this.tasks.size;
    return {
      total,
      completed: completedCount,
      inProgress: inProgressCount,
      pending: pendingCount,
      blocked: blockedCount,
      progress: total > 0 ? (completedCount / total) * 100 : 100,
      isComplete: remaining.length === 0,
      iterations: this.iterations,
      elapsedMs: Date.now() - this.startTime,
      remainingTasks: remaining,
    };
  }

  /**
   * Check whether the swarm should continue running.
   * Returns true if there are remaining tasks AND limits are not exceeded.
   */
  shouldContinue(): boolean {
    if (!this.config.enabled) return false;

    const state = this.getState();
    if (state.isComplete) return false;
    if (this.iterations >= this.config.maxIterations) return false;

    const elapsedMinutes = state.elapsedMs / 60000;
    if (elapsedMinutes >= this.config.timeoutMinutes) return false;

    return true;
  }

  /**
   * Get remaining tasks sorted by priority (in_progress first, then pending).
   * Accepts optional pre-computed state to avoid redundant iteration.
   */
  getRemainingTasks(precomputed?: CompletionState): SwarmTask[] {
    const state = precomputed ?? this.getState();
    const priorityMap: Record<string, number> = { in_progress: 0, pending: 1, blocked: 2 };
    return [...state.remainingTasks].sort((a, b) => {
      return (priorityMap[a.status] ?? 3) - (priorityMap[b.status] ?? 3);
    });
  }

  /**
   * Generate a re-engagement prompt for the agent.
   * Includes drift warnings and learning recommendations when available.
   */
  async generateReEngagementPrompt(): Promise<string> {
    const state = this.getState();
    const remaining = this.getRemainingTasks(state);

    if (state.isComplete) {
      if (this.learning) {
        await this.learning.endSwarmTrajectory(state).catch(() => {});
      }
      return `All ${state.total} tasks complete. Swarm finished in ${this.iterations} iterations.`;
    }

    const taskLines = remaining
      .slice(0, 10)
      .map((t, i) => `  ${i + 1}. [${t.status}] ${t.subject}${t.owner ? ` (${t.owner})` : ''}`)
      .join('\n');

    const moreCount = remaining.length > 10 ? remaining.length - 10 : 0;
    const moreText = moreCount > 0 ? `\n  ... and ${moreCount} more` : '';

    const elapsedMin = Math.round(state.elapsedMs / 60000);

    const lines = [
      `Progress: ${Math.round(state.progress)}% (${state.completed}/${state.total})`,
      `Iteration ${this.iterations}/${this.config.maxIterations}, elapsed ${elapsedMin}/${this.config.timeoutMinutes} minutes`,
    ];

    // Add drift warnings
    const driftMetrics = this.driftDetector.getMetrics();
    if (driftMetrics.activeSignals.length > 0) {
      lines.push('');
      lines.push('DRIFT WARNINGS:');
      for (const signal of driftMetrics.activeSignals) {
        lines.push(`  [${signal.severity.toUpperCase()}] ${signal.message}`);
      }
    }

    lines.push('');
    lines.push('Remaining tasks:');
    lines.push(taskLines + moreText);

    // Add learning recommendations if available
    if (this.learning && this.learningInitialized) {
      try {
        const context = await this.learning.getReEngagementContext(remaining);
        if (context.recommendations.length > 0) {
          lines.push('');
          lines.push('LEARNING RECOMMENDATIONS:');
          for (const rec of context.recommendations) {
            lines.push(`  - ${rec}`);
          }
        }
      } catch {
        // Learning recommendations unavailable
      }
    }

    lines.push('');
    lines.push('Continue working on the remaining tasks. Do not stop until all are completed.');

    return lines.join('\n');
  }

  /**
   * Get completion history for learning/analytics.
   */
  getCompletionHistory(): typeof this.completionHistory {
    return [...this.completionHistory];
  }

  /**
   * Get average task completion time.
   */
  getAverageCompletionTime(): number {
    if (this.completionHistory.length === 0) return 0;
    const total = this.completionHistory.reduce((sum, h) => sum + h.duration, 0);
    return total / this.completionHistory.length;
  }

  /**
   * Reset state for a new swarm session.
   */
  reset(): void {
    this.tasks.clear();
    this.iterations = 0;
    this.startTime = Date.now();
    this.completionHistory = [];
    this.driftDetector.reset();
    this.lastDriftCheck = 0;
    this.sessionId = `session-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  }

  /**
   * Get config.
   */
  getConfig(): CompletionConfig {
    return { ...this.config };
  }

  /**
   * Update config.
   */
  setConfig(config: Partial<CompletionConfig>): void {
    this.config = { ...this.config, ...config };
  }

  /**
   * Initialize the learning subsystem (AgentDB + SONA).
   * Returns true if learning became available.
   */
  async initializeLearning(): Promise<boolean> {
    try {
      const { AutopilotLearning } = await import('./autopilot-learning.js');
      this.learning = new AutopilotLearning();
      const available = await this.learning.initialize();
      this.learningInitialized = available;
      if (available) {
        await this.learning.beginSwarmTrajectory(this.sessionId);
      }
      return available;
    } catch {
      this.learningInitialized = false;
      return false;
    }
  }

  /**
   * Get drift detection metrics.
   */
  getDriftMetrics(): DriftMetrics {
    return this.driftDetector.getMetrics();
  }

  /**
   * Get learning subsystem metrics.
   */
  async getLearningMetrics(): Promise<any> {
    if (!this.learning) return { available: false, episodes: 0, patterns: 0, trajectories: 0 };
    try {
      return await this.learning.getMetrics();
    } catch {
      return { available: false, episodes: 0, patterns: 0, trajectories: 0 };
    }
  }

  /**
   * Apply mitigation strategies for detected drift signals.
   */
  private applyMitigation(signals: DriftSignal[]): void {
    for (const signal of signals) {
      const strategy: MitigationStrategy = this.driftDetector.suggestMitigation(signal);
      switch (strategy.action) {
        case 'reprioritize':
          for (const taskId of strategy.taskIds) {
            const task = this.tasks.get(taskId);
            if (task && task.status !== 'completed') {
              task.status = 'pending';
              task.owner = undefined;
            }
          }
          break;
        case 'reassign':
          for (const taskId of strategy.taskIds) {
            const task = this.tasks.get(taskId);
            if (task && task.status !== 'completed') {
              task.owner = undefined;
            }
          }
          break;
        case 'skip':
          for (const taskId of strategy.taskIds) {
            const task = this.tasks.get(taskId);
            if (task && task.status === 'blocked') {
              task.status = 'completed';
              task.completedAt = Date.now();
            }
          }
          break;
        case 'escalate':
          // Escalation is informational — included in re-engagement prompt
          break;
      }
    }
  }

}

export const swarmCompletion = new SwarmCompletionCoordinator();
